def match(orders):
    import heapq

    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    order_info = {}  # id -> dict(side, price, qty, active)
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty
        seq = seq_counter
        seq_counter += 1
        order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                top_info = order_info[top_id]
                if not top_info['active'] or top_info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and top_price > price:
                    break
                trade_qty = min(remaining, top_info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                top_info['qty'] -= trade_qty
                if top_info['qty'] == 0:
                    top_info['active'] = False
                    heapq.heappop(sell_heap)
                # if resting order still has qty, keep it at top of heap

            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(buy_heap, (-price, seq, oid))
                if remaining == qty and remaining > 0:
                    pass
            else:
                order_info[oid]['active'] = False

            if typ == 'limit' and remaining == 0:
                order_info[oid]['active'] = False

        else:  # sell
            while remaining > 0 and buy_heap:
                top_neg_price, top_seq, top_id = buy_heap[0]
                top_price = -top_neg_price
                top_info = order_info[top_id]
                if not top_info['active'] or top_info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if price is not None and top_price < price:
                    break
                trade_qty = min(remaining, top_info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                top_info['qty'] -= trade_qty
                if top_info['qty'] == 0:
                    top_info['active'] = False
                    heapq.heappop(buy_heap)

            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(sell_heap, (price, seq, oid))
            else:
                order_info[oid]['active'] = False

            if typ == 'limit' and remaining == 0:
                order_info[oid]['active'] = False

    return trades

